import json,pathlib
root=pathlib.Path('data/destinations/recreation_centers')
rows=[]
def add(name,address,city,zip,kind,operator,url,programs='',access='Not verified',phone='',hours='',status='candidate',notes='',lon=None,lat=None):
 rows.append(dict(facility_id='regional_%03d'%(len(rows)+1),facility_name=name,address=address,city=city,state='TX',zip=zip,facility_type=kind,operator=operator,programs=programs,access_notes=access,phone=phone,hours=hours,review_status=status,review_notes=notes,source_url=url,source_checked='2026-10-02',source_longitude=lon,source_latitude=lat))
for r in json.loads((root/'raw/austin_open_data/recreation_centers.json').read_text()):
 p=r['location_1'];add(r['recreation_centers'],r['address'],'Austin',r['zip_code'],'recreation_community_center','City of Austin',r.get('website','https://data.austintexas.gov/d/8dff-2vkt'),phone=r.get('phone_number',''),lon=float(p['longitude']),lat=float(p['latitude']),notes='Existing City inventory; programs and access require facility-specific review.')
for r in json.loads((root/'raw/austin_open_data/senior_centers.json').read_text()):
 p=r['location1']['coordinates'];add(r['recreation_centers'],r['address'],'Austin',r['zip_code'],'senior_center','City of Austin','https://data.austintexas.gov/d/3yna-uh9e',phone=r.get('phone',''),lon=p[0],lat=p[1],notes='Dedicated senior center; program eligibility requires review.')
